// Minimal Materialize implementation for browser
var M = M || {};

M.Sidenav = (function () {
  function Sidenav(el) {
    this.el = el;
    this.isOpen = false;
    this.init();
  }

  Sidenav.prototype.init = function () {
    var self = this;

    // Find trigger
    var trigger = document.querySelector('[data-target="' + this.el.id + '"]');
    if (trigger) {
      trigger.addEventListener("click", function (e) {
        e.preventDefault();
        self.toggle();
      });
    }

    // Close on escape
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && self.isOpen) {
        self.close();
      }
    });
  };

  Sidenav.prototype.open = function () {
    this.el.classList.add("open");
    this.isOpen = true;
  };

  Sidenav.prototype.close = function () {
    this.el.classList.remove("open");
    this.isOpen = false;
  };

  Sidenav.prototype.toggle = function () {
    if (this.isOpen) {
      this.close();
    } else {
      this.open();
    }
  };

  return {
    init: function (elements) {
      if (Array.isArray(elements)) {
        return elements.map(function (el) {
          return new Sidenav(el);
        });
      } else {
        return new Sidenav(elements);
      }
    },
  };
})();

// Export as global for app
window.M = M;
